// WorkflowVariableOperator — This enum defines operators for use with approval rules. Should be used as VariableValue WorkflowVariableOperator RuleValue
type WorkflowVariableOperator string

const (
	// WorkflowVariableOperatorLess — Variable value is less than rule value
	WorkflowVariableOperatorLess WorkflowVariableOperator = "LESS"
	// WorkflowVariableOperatorGreater — Variable value is greater than rule value
	WorkflowVariableOperatorGreater WorkflowVariableOperator = "GREATER"
	// WorkflowVariableOperatorLessOrEquals — Variable value is less than or equals rule value
	WorkflowVariableOperatorLessOrEquals WorkflowVariableOperator = "LESS_OR_EQUALS"
	// WorkflowVariableOperatorGreaterOrEquals — Variable value is greater than or equals rule value
	WorkflowVariableOperatorGreaterOrEquals WorkflowVariableOperator = "GREATER_OR_EQUALS"
	// WorkflowVariableOperatorEquals — Variable value equals rule value
	WorkflowVariableOperatorEquals WorkflowVariableOperator = "EQUALS"
	// WorkflowVariableOperatorNotEquals — Variable value does not equal rule value
	WorkflowVariableOperatorNotEquals WorkflowVariableOperator = "NOT_EQUALS"
	// WorkflowVariableOperatorContains — Variable value contains rule value
	WorkflowVariableOperatorContains WorkflowVariableOperator = "CONTAINS"
	// WorkflowVariableOperatorDoesNotContain — Variable value does not contain rule value
	WorkflowVariableOperatorDoesNotContain WorkflowVariableOperator = "DOES_NOT_CONTAIN"
	// WorkflowVariableOperatorChanged — Variable value changed
	WorkflowVariableOperatorChanged WorkflowVariableOperator = "CHANGED"
)

// ValidWorkflowVariableOperator returns all valid values for WorkflowVariableOperator.
func ValidWorkflowVariableOperator() []WorkflowVariableOperator {
	return []WorkflowVariableOperator{
		WorkflowVariableOperatorLess,
		WorkflowVariableOperatorGreater,
		WorkflowVariableOperatorLessOrEquals,
		WorkflowVariableOperatorGreaterOrEquals,
		WorkflowVariableOperatorEquals,
		WorkflowVariableOperatorNotEquals,
		WorkflowVariableOperatorContains,
		WorkflowVariableOperatorDoesNotContain,
		WorkflowVariableOperatorChanged,
	}
}
